Q: How would I create elements that float/move in the background? A: <p>This is a combination of several CSS and JS concepts. Use a container to hold your heart SVGs and set the position to <code>fixed</code> with <code>inset: 0</code>. The SVG hearts should float, and you can use an animation to blur them. Finally, JavaScript should handle the randomized movement</p>
<pre class="lang-html prettyprint-override"><code>&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;en&quot;&gt;
&lt;head&gt;
    &lt;meta charset=&quot;UTF-8&quot;&gt;
    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;
    &lt;title&gt;Floating Hearts Background&lt;/title&gt;

    &lt;style&gt;
        :root {
            --heart-color: purple;
            --bg-color: #ffffff;
        }

        body {
            margin: 0;
            padding: 0;
            background-color: var(--bg-color);
        }

        #background-container {
            position: fixed;
            inset: 0; /* Modern shorthand for top/left/right/bottom: 0 */
            z-index: -1;
            overflow: hidden;
            pointer-events: none; /* Ensures background doesn't block clicks */
        }

        .heart-wrapper {
            position: absolute;
            will-change: transform; /* Performance optimization */
            animation: blurLoop 4s ease-in-out infinite alternate;
        }

        .heart-wrapper svg {
            width: 100%;
            height: 100%;
            display: block;
        }

        @keyframes blurLoop {
            0% { 
                filter: blur(0px); 
                opacity: 0.9; 
            }
            100% { 
                filter: blur(10px); 
                opacity: 0.3; 
            }
        }
    &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;

    &lt;div id=&quot;background-container&quot;&gt;&lt;/div&gt;

    &lt;!-- Heart SVG Definition --&gt;
    &lt;svg style=&quot;display: none;&quot;&gt;
        &lt;symbol id=&quot;heart-svg&quot; viewBox=&quot;0 0 32 32&quot;&gt;
            &lt;path 
                d=&quot;M16 28.5L14.1 26.8C7.3 20.7 2.8 16.6 2.8 11.6C2.8 7.5 6 4.3 10.1 4.3C12.4 4.3 14.6 5.4 16 7.1C17.4 5.4 19.6 4.3 21.9 4.3C26 4.3 29.2 7.5 29.2 11.6C29.2 16.6 24.7 20.7 17.9 26.8L16 28.5Z&quot; 
                fill=&quot;none&quot; 
                stroke=&quot;var(--heart-color)&quot; 
                stroke-width=&quot;2&quot;
                stroke-linejoin=&quot;round&quot;
            /&gt;
        &lt;/symbol&gt;
    &lt;/svg&gt;

    &lt;script&gt;
        class HeartAnimation {
            constructor(containerId, count = 12) {
                this.container = document.getElementById(containerId);
                this.count = count;
                this.hearts = [];
                this.viewport = { width: window.innerWidth, height: window.innerHeight };

                this.init();
                window.addEventListener('resize', () =&gt; this.handleResize());
            }

            init() {
                for (let i = 0; i &lt; this.count; i++) {
                    this.hearts.push(this.createHeart());
                }
                this.animate();
            }

            createHeart() {
                const size = Math.random() * 40 + 30;
                const el = document.createElement('div');
                el.className = 'heart-wrapper';
                el.innerHTML = `&lt;svg&gt;&lt;use href=&quot;#heart-svg&quot;/&gt;&lt;/svg&gt;`;

                // Styling
                el.style.width = `${size}px`;
                el.style.height = `${size}px`;
                el.style.animationDelay = `${Math.random() * 5}s`;

                const heart = {
                    el,
                    size,
                    x: Math.random() * (this.viewport.width - size),
                    y: Math.random() * (this.viewport.height - size),
                    dx: (Math.random() - 0.5) * 3, // Horizontal velocity
                    dy: (Math.random() - 0.5) * 3  // Vertical velocity
                };

                this.container.appendChild(el);
                return heart;
            }

            handleResize() {
                this.viewport.width = window.innerWidth;
                this.viewport.height = window.innerHeight;
            }

            animate() {
                this.hearts.forEach(h =&gt; {
                    h.x += h.dx;
                    h.y += h.dy;

                    // Bounce logic (DVD Style)
                    if (h.x &lt;= 0 || h.x + h.size &gt;= this.viewport.width) {
                        h.dx *= -1;
                        h.x = Math.max(0, Math.min(h.x, this.viewport.width - h.size));
                    }
                    if (h.y &lt;= 0 || h.y + h.size &gt;= this.viewport.height) {
                        h.dy *= -1;
                        h.y = Math.max(0, Math.min(h.y, this.viewport.height - h.size));
                    }

                    h.el.style.transform = `translate(${h.x}px, ${h.y}px)`;
                });

                requestAnimationFrame(() =&gt; this.animate());
            }
        }

        // Initialize the animation
        new HeartAnimation('background-container', 15);
    &lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

Q: document.createElement(&#39;script&#39;)... adding two scripts with one callback A: <p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const loadScript = url =&gt; 
  new Promise((resolve, reject) =&gt; {
    const script = document.createElement("script");
    script.src = url;
    script.onload = resolve;
    script.onerror = e =&gt; 
      reject(Error(`${url} failed to load`))
    ;
    document.head.appendChild(script);
  })
;

const scriptURLs = [
  "https://unpkg.com/htm",
