    console.log(d3.csvParse("a,b\n3,4\n5,6"));
    const html = htm.bind((t, p, ...c) =&gt; ({t, p, c}));
    console.log(html`&lt;h1 id=hello&gt;Hello world!&lt;/h1&gt;`);
  })
